// @ts-check
/**
 * fontCatalog -- the list of online fonts the Document properties font picker
 * searches.
 *
 * The data (src/data/fontCatalog.json, regenerated by
 * `npm run fonts:catalog`) ships WITH the editor and is loaded lazily, so typing
 * a font name never makes a network request. Only the one font the user picks is
 * downloaded, from the source they chose (utils/fontSources.js).
 *
 * Pure: no React/Redux/MUI, no fetch; never throws.
 *
 * @typedef {'sans-serif'|'serif'|'display'|'handwriting'|'monospace'} FontCategory
 * @typedef {{ id: string, family: string, category: FontCategory, weight: number, hasBold: boolean }} CatalogFont
 *   `weight` is the regular face to load (400 when the font has it); `hasBold`
 *   is true when a real 700 face exists.
 * @typedef {[string, string, string, number, number]} CatalogRow
 */

/** @type {Record<string, FontCategory>} */
const CATEGORY_CODES = {
  s: 'sans-serif',
  r: 'serif',
  d: 'display',
  h: 'handwriting',
  m: 'monospace',
};

/**
 * Expand the compact JSON rows into CatalogFont objects, skipping bad rows.
 * @param {unknown} rows
 * @returns {CatalogFont[]}
 */
export function parseCatalog(rows) {
  if (!Array.isArray(rows)) return [];
  /** @type {CatalogFont[]} */
  const out = [];
  for (const row of rows) {
    if (!Array.isArray(row) || row.length < 5) continue;
    const [id, family, code, weight, bold] = row;
    if (typeof id !== 'string' || typeof family !== 'string' || !CATEGORY_CODES[code]) continue;
    out.push({
      id,
      family,
      category: CATEGORY_CODES[code],
      weight: Number.isFinite(weight) ? weight : 400,
      hasBold: bold === 1 || bold === true,
    });
  }
  return out;
}

/**
 * The catalog entry for a family name (case-insensitive), or undefined.
 * @param {CatalogFont[]} catalog
 * @param {string|null|undefined} family
 * @returns {CatalogFont|undefined}
 */
export function findFont(catalog, family) {
  if (!Array.isArray(catalog) || typeof family !== 'string') return undefined;
  const key = family.trim().toLowerCase();
  if (!key) return undefined;
  return catalog.find((f) => f.family.toLowerCase() === key);
}

/**
 * Search the catalog. Ranking: exact match, then family starts with the query,
 * then a word in the family starts with it, then the query appears anywhere.
 * Within a rank, handwriting fonts first (they suit sketchy wireframes), then
 * alphabetical. An empty query lists handwriting fonts first.
 * @param {CatalogFont[]} catalog
 * @param {string} query
 * @param {number} [limit] default 50
 * @returns {CatalogFont[]}
 */
export function searchFonts(catalog, query, limit = 50) {
  if (!Array.isArray(catalog)) return [];
  const q = typeof query === 'string' ? query.trim().toLowerCase() : '';
  /** @type {Array<{ font: CatalogFont, rank: number }>} */
  const hits = [];
  for (const font of catalog) {
    const name = font.family.toLowerCase();
    let rank;
    if (!q) rank = 0;
    else if (name === q) rank = 0;
    else if (name.startsWith(q)) rank = 1;
    else if (name.split(/[\s_.-]+/).some((w) => w.startsWith(q))) rank = 2;
    else if (name.includes(q)) rank = 3;
    else continue;
    hits.push({ font, rank });
  }
  hits.sort((a, b) => a.rank - b.rank
    || Number(b.font.category === 'handwriting') - Number(a.font.category === 'handwriting')
    || a.font.family.localeCompare(b.font.family));
  return hits.slice(0, Math.max(0, limit)).map((h) => h.font);
}

/**
 * Load the bundled catalog (a lazily-loaded chunk of the app itself, so it comes
 * from the editor's own origin, never a third party). Cached after first call.
 * @returns {Promise<CatalogFont[]>}
 */
let catalogPromise = null;
export function loadCatalog() {
  if (!catalogPromise) {
    catalogPromise = import('../data/fontCatalog.json')
      .then((mod) => parseCatalog(mod.default ?? mod))
      .catch(() => {
        catalogPromise = null;
        return [];
      });
  }
  return catalogPromise;
}
